-- ============================================================
-- 外研社九上 s4 语法灌库(junior_grammar_points / junior_grammar_questions)
-- publisher='junior_fltrp' · volume='wy9A' · grade=9 · 6 语法点 / 90 题
-- 幂等:按 (publisher, volume) 先删后插,可安全重跑。
-- code 一律 wy9a- 前缀(防跨册撞 code 全局唯一约束;七上与高中 required2/3 都踩过)。
-- explanation 只含语法解释,审校备注与来源不进 DB。
-- 六单元 90 题已全部经 Aaron 审核通过;造稿过程经 clause_gate / comparative_gate /
--   past_perfect_gate / 词表超前 四道门全绿(审核件见 REVIEWAA/wy9A/)。
-- ============================================================

BEGIN;

-- 1) 幂等删除:先删本册题(经 point 关联),再删本册点
DELETE FROM public.junior_grammar_questions q
 USING public.junior_grammar_points p
 WHERE q.point_id = p.id AND p.publisher='junior_fltrp' AND p.volume='wy9A';
DELETE FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A';

-- 2) 插入 6 个语法点(cefr=B1 承接八年级 A2;content_depth=0 同四册)
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u1-adverbial-conditional-reason', '条件状语从句和原因状语从句', 'B1', 9, '条件状语从句由 if 引导,表示尚未发生的假设条件。从句用一般现在时表示将来,主句用一般将来时或情态动词,即「主将从现」;主句也可以是祈使句(If you want to know more, call now.)。原因状语从句常由 because 引导,直接说明原因,可用来回答 why;since 引导时表示「既然」,用于说明已为人所知或显而易见的理由。从句既可放在主句之前,也可放在主句之后。', 1, 'wy9A', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='clause' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u2-adverbial-time-place', '时间状语从句和地点状语从句', 'B1', 9, '时间状语从句常用引导词:when(当……时)、as soon as(一……就……)、before/after(在……之前/之后)、while(在……过程中,从句多用持续性动词与进行时)、until(直到……为止,not…until 表示「直到……才」)、since(自从,主句常用现在完成时)。从句用一般现在时表示将来,不用 will。地点状语从句由 where、wherever、anywhere 引导,其前没有先行词,整个从句作状语。', 2, 'wy9A', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='clause' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u3-adverbial-purpose-result', '目的状语从句和结果状语从句', 'B1', 9, '目的状语从句由 so that 引导,说明主句动作的目的,从句中通常含有 can/could/will/would/may 等表示可能性的词。结果状语从句由 so… that 或 such… that 引导,表示程度导致的结果:so 直接修饰形容词或副词(so beautiful that…),such 后接「a/an + 形容词 + 名词」(such a valuable find that…)。判断要点:表目的用 so that,表结果用 so/such… that。', 3, 'wy9A', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='clause' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u4-attributive-who', 'who 引导的定语从句', 'B1', 9, '定语从句用来修饰前面的名词(先行词)。先行词指人时,用 who 引导;who 在从句中作主语(the boy who won the prize)。若引导词在从句中作宾语,则用 who 的宾格形式 whom(the person whom we met)。定语从句的谓语要与先行词的数保持一致(the boy who is… / the people who are…);注意 one of the + 复数名词 + who 结构中,先行词是复数名词而非 one。who 只能指人,不能用 which 代替。', 4, 'wy9A', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='clause' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u5-attributive-that-which', 'that 和 which 引导的定语从句', 'B1', 9, 'that 引导的定语从句既可修饰人也可修饰物,在从句中作主语或宾语;which 引导的定语从句一般只修饰物,在从句中作主语或宾语。★引导词省略规则★:引导词在从句中作宾语时通常可以省略(the book (that) I read),作主语时不能省略,否则从句就没有主语(the book that changed me)。省略引导词后的定语从句仍然修饰先行词,如 The film we saw yesterday was great。', 5, 'wy9A', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='clause' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy9a-u6-word-formation', '构词法(派生·转化·合成)', 'B1', 9, '派生法:加前缀或后缀构成新词。常见前缀 un-/dis- 表否定(uninteresting, disable)、en- 表使动(enable)、re- 表重复(reuse)、up- 表提升(upcycle);常见后缀 -ful 表「有……的」(helpful)、-less 表「没有……的」(helpless)、-ly 构成副词(loudly)、-al 构成形容词(environmental)、-ity/-ation 构成名词(ability, imagination)。注意 -ed 形式的形容词说明人的感受,-ing 形式说明事物的性质。转化法:词形不变而词性改变,如 talk(动词→名词)、water(名词→动词),判断依据是它在句中的位置。合成法:两词合成一词,如 long-lasting。', 6, 'wy9A', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);

-- 3) 插入 90 道题(按 code 挂 point_id)
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), '____ you want to join the volunteer group, come to Room 302 after school.', 'If', 'Because', 'Though', 'So', 'A', 'if 引导条件状语从句,后接祈使句,表示「如果……,就……吧」。because/though/so 都不能引出条件并接祈使句。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'The video was flooded with messages ____ the young performer amazed everyone.', 'if', 'because', 'unless', 'or', 'B', 'because 引导原因状语从句,说明「消息大量涌来」的原因。if 表条件、unless 表否定条件、or 表选择,均不合此处因果关系。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'I feel interested in puppets ____ my grandpa is a performer.', 'if', 'or', 'because', 'but', 'C', 'because 引导原因状语从句,交代「我对木偶感兴趣」的理由。but 表转折、or 表选择、if 表条件,都不表示原因。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'You will be late for the performance ____ you do not hurry.', 'because', 'since', 'so', 'if', 'D', 'if 引导条件状语从句:从句提出假设条件,主句用一般将来时表示结果。because/since 表原因,so 是并列连词,均不合。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), '—Why do you like this programme?  —____ it tells the story of a young hero.', 'Because', 'If', 'So', 'And', 'A', '对 why 提问的回答用 because 说明原因。if 表条件、so 表结果、and 表并列,都不能回答 why。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'Call the teacher ____ you feel ill at school.', 'because', 'if', 'so', 'but', 'B', 'if 引导条件状语从句,可放在主句之后;主句为祈使句,表示「如果……就……」。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'This old-fashioned art is coming back ____ many teenagers post videos about it.', 'if', 'unless', 'because', 'or', 'C', 'because 引导原因状语从句,说明这门艺术回归的原因。unless 表「除非」、if 表条件,均与因果不符。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'If you ____ hard this term, you will pass the exam easily.', 'will work', 'worked', 'are working', 'work', 'D', 'if 引导的条件状语从句用一般现在时表示将来,主句用一般将来时,即「主将从现」。从句不能用 will。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'If it ____ tomorrow, we will not go to the park.', 'rains', 'rain', 'will rain', 'rained', 'A', '「主将从现」:从句用一般现在时,主语 it 为第三人称单数,谓语用 rains;主句用 will not go。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), '—Everyone has arrived.  —Good. ____ we are all here, let us start the show.', 'If', 'Since', 'Unless', 'Or', 'B', '前句已说明「大家都到了」是既成事实,故用 since 表示「既然」引出已知理由。if 表尚未确定的假设,与已知事实矛盾。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'If you want to know what to see, ____ the guide first.', 'reading', 'to read', 'read', 'reads', 'C', 'if 从句 + 祈使句结构中,主句为祈使句,动词用原形 read。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'She may join our group if she ____ free on Saturday.', 'will be', 'was', 'being', 'is', 'D', 'if 引导的条件状语从句用一般现在时,主语 she 后用 is;主句用情态动词 may 表示可能的结果。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'This art was not popular at first. ____ Zhan Haojing gave puppet shows at schools, more young people got to know it.', 'Because', 'If', 'Unless', 'Or', 'A', '两句构成因果关系:后一句是前一句情况改变的原因,故用 because 引导原因状语从句。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'Some of these local arts may soon disappear ____ we do not take action now.', 'because', 'if', 'since', 'so', 'B', '「现在不采取行动」是尚未发生的假设条件,用 if 引导条件状语从句;because/since 表已成立的原因,与「may soon disappear」的假设语气不符。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u1-adverbial-conditional-reason'), 'I felt less close to the art ____ people thought puppets were old-fashioned. But now everything is different.', 'if', 'unless', 'because', 'or', 'C', 'because 引导原因状语从句,说明「我曾与这门艺术疏远」的原因。后句 But now… 与之呼应,证实是已发生的原因而非假设。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'I will call you ____ I get to the bank.', 'before', 'when', 'until', 'since', 'B', 'when 引导时间状语从句,表示「到达银行的时候」这一时间点;主句用一般将来时,从句用一般现在时。before/until/since 与此处时间关系不符。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), '____ the shop opened, many people went in.', 'When', 'Until', 'Since', 'Unless', 'A', 'when 引导时间状语从句,表示「商店开门时」这一时间点。since 表「自从」,主句需用完成时;until 表「直到」,均与后句 went in 不搭。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'Please put the moneybox back ____ you found it.', 'when', 'until', 'before', 'where', 'D', 'where 引导地点状语从句,表示「放回你找到它的地方」。where 前没有先行词,整个从句作状语。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'We waited ____ the price went down.', 'before', 'where', 'until', 'since', 'C', 'until 引导时间状语从句,表示动作一直持续到某一时刻,即「一直等到价格下降」。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), '____ I finish my homework, I will help you count the coins.', 'After', 'Until', 'Where', 'Unless', 'A', 'after 引导时间状语从句,表示主句动作发生在从句动作之后;从句用一般现在时表示将来。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'He put his savings in the bank ____ he was ten.', 'until', 'when', 'where', 'after', 'B', 'when 引导时间状语从句,表示「他十岁的时候」这一时间点。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'You can buy it ____ you like — online or in a real shop.', 'when', 'until', 'wherever', 'before', 'C', 'wherever 引导地点状语从句,表示「无论在哪里」。破折号后的两种地点正说明是地点而非时间。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'While we ____ for the bus, let us check the price on the website.', 'wait', 'waited', 'will wait', 'are waiting', 'D', 'while 引导的时间状语从句表示一个持续进行的动作,从句谓语常用进行时,故用 are waiting。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'I have known Bill ____ he was born.', 'when', 'since', 'until', 'after', 'B', 'since 引导时间状语从句表示「自从」,主句常用现在完成时(have known)与之呼应。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'We did not leave the shop ____ we counted every penny.', 'while', 'when', 'until', 'before', 'C', 'not … until 表示「直到……才」,until 引导时间状语从句,说明动作持续到从句所指的时刻。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'As soon as the sale ____, we will go and buy the T-shirt.', 'begins', 'began', 'will begin', 'beginning', 'A', 'as soon as 引导时间状语从句,表示「一……就……」;从句用一般现在时表示将来,主句用一般将来时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'Before you ____ the money, please write down the date.', 'will spend', 'spent', 'spending', 'spend', 'D', 'before 引导时间状语从句,从句用一般现在时表示将来的动作,不能用 will;主句为祈使句。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'Choose the word that fits BOTH blanks: "____ everyone has arrived, let us begin."  /  "I have kept my savings ____ I was ten."', 'when', 'because', 'since', 'until', 'C', 'since 有两种用法:引导原因状语从句表示「既然」(第一句,说明已知理由);引导时间状语从句表示「自从」(第二句,主句用现在完成时 have kept)。判断依据是主句时态与语境。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'I always check the price ____ I pay, so I never spend more than my budget.', 'before', 'after', 'until', 'since', 'A', '先看价格、后付钱,故用 before 引导时间状语从句表示主句动作在其之前发生。若用 after 则先后颠倒,与「从不超支」的结果矛盾。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u2-adverbial-time-place'), 'My grandpa says a penny is worth saving ____ you live — in a big city or a small town.', 'when', 'wherever', 'until', 'since', 'B', 'wherever 引导地点状语从句,表示「无论住在哪里」;破折号后列举的两个地点证实此处问的是地点而非时间。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'We went to the museum early ____ we could see the new collection.', 'because', 'until', 'so that', 'as soon as', 'C', 'so that 引导目的状语从句,表示「为了能……」;从句常与 could/can/would 等表示可能性的词连用。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'The old silk was ____ beautiful that everyone stopped to look at it.', 'such', 'very', 'too', 'so', 'D', 'so 修饰形容词 beautiful,与 that 从句构成「如此……以至于……」的结果状语从句。such 只能修饰名词。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'It was ____ a valuable find that the news went around the world.', 'such', 'so', 'very', 'quite', 'A', 'such 后接「a + 形容词 + 名词」构成结果状语从句;so 只能直接修饰形容词或副词,不能带冠词与名词。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'The archaeologist spoke slowly ____ we could all understand him.', 'until', 'so that', 'before', 'where', 'B', 'so that 引导目的状语从句,说明「说得慢」的目的是让大家都能听懂。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'They worked ____ carefully that nothing was broken.', 'such', 'very', 'too', 'so', 'D', 'so 修饰副词 carefully,与 that 从句构成结果状语从句。such 不能修饰副词。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'Take a photo of the design ____ we can study it at home.', 'because', 'until', 'so that', 'though', 'C', 'so that 引导目的状语从句,表示拍照的目的;从句用 can 表示能够。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'He is ____ a careful worker that we all take pride in him.', 'so', 'such', 'very', 'too', 'B', 'such 后接「a + 形容词 + 名词」;so 不能直接修饰名词短语。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'The museum keeps the room cool ____ the silk may last longer.', 'so that', 'so', 'such', 'because', 'A', 'so that 引导目的状语从句,从句用情态动词 may 表示希望达成的结果。若用 because 则变成解释原因,与「保持房间凉爽是手段」的语义不符。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'It was such ____ interesting cartoon that we watched it twice.', 'a very', 'the', 'an', 'so', 'C', 'such 后接单数可数名词时须加冠词;interesting 以元音音素开头,故用 an。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'The design was so ____ that it soon became a hit.', 'a pretty', 'pretty', 'such pretty', 'pretty a', 'B', 'so 直接修饰形容词,后面不加冠词;「so + 形容词 + that 从句」构成结果状语从句。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'We saved every piece ____ the museum could bring them out again.', 'because', 'until', 'such that', 'so that', 'D', 'so that 引导目的状语从句,说明保存每一块碎片的目的;从句用 could 与主句过去时呼应。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), '—Why did they build the wall here?  —____ the wind could not break the young trees.', 'So that', 'So', 'Such', 'Because', 'A', '问句问的是建墙的目的,故用 so that 引导目的状语从句,并用 could not 表示要避免的结果。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'Which sentence expresses PURPOSE, not result?', 'The find was so important that it made the news.', 'They dug slowly so that nothing would break.', 'It was such a big find that everyone came.', 'The room was so dark that we turned on more lights.', 'B', 'so that 引导目的状语从句,表示做某事「为了」达成什么;而 so/such … that 引导结果状语从句,表示程度导致的结果。B 项说明「慢慢挖」的目的,其余三项都是「如此……以至于……」的结果。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'It was ____ that the whole team took pride in the work.', 'so a great success', 'such great a success', 'so great success', 'such a great success', 'D', 'such 后接「a + 形容词 + 名词」的语序;so 只能修饰形容词或副词本身,不能带冠词与名词,故其余三项语序或搭配均不成立。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u3-adverbial-purpose-result'), 'Choose the pair that fits: "We turned on more lights ____ the visitors ____ see the small designs on the silk."', 'so; could', 'such; can', 'so that; could', 'so that; can', 'C', '空一需要引导目的状语从句的 so that;空二的情态动词要与主句谓语 turned on 的过去时呼应,故用 could 而非 can。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The person ____ helped us find the way was very gentle.', 'which', 'what', 'whose', 'who', 'D', 'who 引导定语从句,先行词 the person 指人,who 在从句中作主语。which 只能指物,what 不能引导定语从句。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'Do you know the fighter ____ saved the little girl?', 'which', 'what', 'who', 'where', 'C', '先行词 the fighter 指人,故用 who 引导定语从句并在从句中作主语。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'He is the presenter ____ we saw on TV last night.', 'which', 'whom', 'what', 'where', 'B', '先行词 the presenter 指人,关系词在从句中作 saw 的宾语,故用 who 的宾格形式 whom。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The survivor ____ told the story is my great-aunt.', 'who', 'which', 'whose', 'what', 'A', '先行词 the survivor 指人,who 在从句中作主语,引导定语从句修饰 survivor。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'We thanked the doctors ____ worked on the front line.', 'which', 'what', 'who', 'where', 'C', '先行词 the doctors 指人,用 who 引导定语从句;which 只用于指物。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'I still remember the teacher ____ made me love science.', 'which', 'what', 'where', 'who', 'D', '先行词 the teacher 指人,故用 who;从句 made me love science 说明是哪一位老师。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The dreamer ____ fed countless people is remembered by us all.', 'who', 'which', 'what', 'whose', 'A', '先行词 the dreamer 指人,who 在从句中作主语。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The boy who ____ standing by the engine is my cousin.', 'are', 'is', 'were', 'be', 'B', '定语从句的谓语要与先行词的数一致:先行词 the boy 是单数,故用 is。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The people who ____ on the front line are true heroes.', 'is', 'was', 'has', 'work', 'D', '先行词 the people 是复数概念,定语从句谓语用复数形式 work。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'The person whom we ____ yesterday is a co-pilot.', 'met', 'meet', 'meets', 'meeting', 'A', '定语从句由时间状语 yesterday 决定用一般过去时 met;whom 在从句中作 met 的宾语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'My great-aunt is the person ____ I want to thank most.', 'which', 'what', 'whom', 'where', 'C', '先行词 the person 指人,关系词在从句中作 thank 的宾语,故用 whom。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'Anyone ____ wants to help with the experiment can join us.', 'which', 'who', 'what', 'where', 'B', '不定代词 anyone 指人,用 who 引导定语从句;从句谓语 wants 与 anyone 的单数一致。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'Which sentence has an ATTRIBUTIVE CLAUSE (定语从句)?', 'The girl who won the race is my sister.', 'I know who won the race.', 'Who won the race yesterday?', 'Please tell me who won the race.', 'A', '定语从句的 who 前面有先行词,用来修饰该名词;A 项中 who won the race 修饰 the girl。B、D 两项的 who 引导宾语从句,作 know / tell 的宾语,前面没有先行词;C 项是疑问句。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'She is one of the few people who ____ the whole story.', 'knows', 'is knowing', 'to know', 'know', 'D', '定语从句修饰的先行词是 people(复数),故谓语用 know;不要被前面的 one of 误导为单数。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u4-attributive-who'), 'Choose the CORRECT sentence.', 'This is the engine who works well.', 'This is the pilot who flies the plane.', 'This is the pilot which flies the plane.', 'This is the engine whom works well.', 'B', 'who 只能指人,which 只能指物。B 项先行词 the pilot 指人、用 who 且在从句中作主语,搭配正确;A、D 两项先行词 the engine 指物却用了 who / whom,C 项先行词指人却用了 which。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The film ____ tells of an adventure is very interesting.', 'that', 'who', 'what', 'where', 'A', 'that 引导定语从句,可以修饰物;此处 that 在从句中作主语,修饰先行词 the film。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'This is the photo ____ we liked best.', 'who', 'which', 'what', 'whose', 'B', 'which 引导定语从句修饰物,在从句中作 liked 的宾语。who 只指人,what 不能引导定语从句。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The animals ____ live in the forest need our protection.', 'who', 'what', 'where', 'that', 'D', 'that 引导定语从句,可修饰人也可修饰物,此处修饰 the animals 并在从句中作主语。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The writer ____ I like best is Mark Twain.', 'which', 'what', 'that', 'where', 'C', 'that 既可修饰人也可修饰物;此处修饰指人的先行词 the writer,并在从句中作 like 的宾语。which 不能指人。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'A group of photos ____ show our city won the prize.', 'who', 'which', 'what', 'whose', 'B', 'which 引导定语从句修饰物 photos,并在从句中作主语。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The organisation ____ protects endangered animals started ten years ago.', 'that', 'who', 'what', 'where', 'A', 'that 引导定语从句修饰 the organisation 并在从句中作主语。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'Please read the notice ____ is on the wall.', 'who', 'what', 'that', 'whose', 'C', 'that 引导定语从句修饰物 the notice,在从句中作主语,故不能省略。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The rubbish ____ people drop in the park harms wild animals.', 'who', 'what', 'where', 'that', 'D', 'that 引导定语从句修饰 the rubbish,在从句中作 drop 的宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The tourist we met yesterday ____ from Australia.', 'is', 'are', 'be', 'being', 'A', 'we met yesterday 是省略了引导词的定语从句,修饰 the tourist;句子的主语仍是单数 the tourist,故主句谓语用 is。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The gas ____ cars give out affects the air.', 'who', 'what', 'which', 'where', 'C', 'which 引导定语从句修饰物 the gas,在从句中作 give out 的宾语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'The solar panel ____ they put on the roof works well.', 'who', 'that', 'what', 'whose', 'B', 'that 引导定语从句修饰 the solar panel,在从句中作 put 的宾语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'In the sentence "The alarm we heard last night was very loud", the words "we heard last night" ____.', 'ask a question about the alarm', 'act as the main clause of the sentence', 'tell us who bought the alarm', 'tell us which alarm is being talked about', 'D', 'we heard last night 是省略了引导词的定语从句,用来说明是哪一个 alarm;主句是 The alarm … was very loud。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'In which sentence can the word THAT be LEFT OUT?', 'The alarm that rings at seven wakes me up.', 'The guard that stands at the gate is friendly.', 'The photo that we took by the river is lovely.', 'The rubbish that lies on the ground harms animals.', 'C', '引导词在从句中作宾语时可以省略,作主语时不能省略。C 项的 that 是 took 的宾语,可省;A、B、D 三项的 that 都是从句主语,省略后从句就没有主语了。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'Choose the sentence that has a relative clause with NO relative word.', 'The tourist we met at the station came from far away.', 'The tourist who met us was very kind.', 'We do not know who met the tourist.', 'Which tourist met you at the station?', 'A', 'A 项中 we met at the station 修饰 the tourist,是省略了引导词的定语从句。B 项引导词 who 仍在;C 项是宾语从句;D 项是疑问句。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u5-attributive-that-which'), 'Choose the CORRECT sentence.', 'The man which helped us is a guard.', 'The plan who we made is working.', 'The river which we cleaned it is clean now.', 'The plan that we made last year is working now.', 'D', 'which 只能指物、不能指人,故 A 错;who 只能指人、不能指物,故 B 错;C 项的引导词 which 已在从句中作宾语,后面不应再出现 it;D 项 that 修饰物且在从句中作 made 的宾语,正确。', 3, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'The old map was ____, so we could not find the way.', 'useful', 'useless', 'using', 'used', 'B', '形容词后缀 -less 表示「没有……的」,useless 意为「无用的」,与「找不到路」的结果一致;-ful 表示「有……的」,语义相反。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'Reading this book is very ____; I have learnt a lot from it.', 'helpless', 'helplessly', 'helpful', 'helpfully', 'C', '-ful 加在名词 help 后构成形容词 helpful「有帮助的」,在句中作表语;-less 表否定,-ly 构成副词,均不合。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'The new machine will ____ us to save more energy.', 'enable', 'unable', 'ability', 'disable', 'A', '前缀 en- 加在形容词 able 前构成动词 enable「使能够」,后接「sb. to do」;unable 是形容词,ability 是名词,disable 意为「使丧失能力」,语义相反。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'He spoke ____ so that everyone at the back could hear him.', 'loud', 'louder', 'loudest', 'loudly', 'D', '后缀 -ly 加在形容词 loud 后构成副词 loudly,修饰动词 spoke。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'I am not ____ in this old film at all.', 'interesting', 'interestingly', 'interested', 'uninteresting', 'C', '-ed 形式的形容词说明人的感受,主语是 I,故用 interested;-ing 形式说明事物本身令人产生某种感受。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), '"Please water the plants twice a week." In this sentence, the word "water" is used as a ____.', 'noun', 'verb', 'adjective', 'adverb', 'B', '转化法:名词 water 在此句中直接用作动词,意为「浇水」,前面有祈使句标志 Please,后面带宾语 the plants。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'Do not throw the old glass bottles away — we can ____ them into lamps.', 'use', 'used', 'using', 'upcycle', 'D', '前缀 up- 加在 cycle 前构成动词 upcycle,意为「升级改造」,即把旧物改造成更好的新物。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'Without a map we felt ____ in the big city.', 'helpless', 'helpful', 'helpfully', 'helping', 'A', '-less 表示「没有……的」,helpless 意为「无助的」,说明主语 we 的状态;helpful 意为「有帮助的」,语义相反。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'This kind of plastic is ____; it stays in the soil for hundreds of years.', 'long', 'long-lasting', 'longer', 'longest', 'B', '合成法:形容词 long 与 lasting 合成 long-lasting「耐用的、持久的」,与后半句「留存数百年」呼应。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'She has the ____ to solve the problem by herself.', 'able', 'unable', 'enable', 'ability', 'D', '冠词 the 后面需要名词,故用 able 的名词形式 ability「能力」。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'The film was ____, so we left before the end.', 'interested', 'interestingly', 'uninteresting', 'uninterested', 'C', '前缀 un- 表否定,uninteresting 意为「无趣的」,-ing 形式说明事物本身的性质,主语是 The film。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'The factory must think about the ____ cost of its work.', 'environmental', 'environment', 'environmentally', 'environments', 'A', '后缀 -al 加在名词 environment 后构成形容词 environmental「环境的」,修饰名词 cost。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'In which sentence is the word TALK used as a NOUN?', 'Let us talk about it after class.', 'They talk too loudly in the library.', 'I want to talk to the guard.', 'We had a long talk about upcycling.', 'D', '转化法中同一个词可作不同词性,判断依据是它在句中的位置。D 项 talk 前有冠词 a 和形容词 long,作 had 的宾语,是名词;其余三项的 talk 都跟在 to 或主语之后作动词。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'Choose the pair that fits: "The teacher was very ____, so the lesson became ____."', 'helpless; interested', 'helpful; interesting', 'helpfully; interestingly', 'helpful; interested', 'B', '空一修饰人、表示「给予帮助的」,用 -ful 形式 helpful;空二的主语是 the lesson(事物),说明事物本身的性质,用 -ing 形式 interesting。D 项的 interested 只能说明人的感受。', 3, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy9A' AND code='wy9a-u6-word-formation'), 'The word UPCYCLE means to change old things into something ____.', 'better and new', 'smaller and cheap', 'old and broken', 'dirty and unsafe', 'A', '前缀 up- 有「向上、提升」之意,upcycle 指把旧物改造成更好、更有价值的新东西,与单纯的 recycle(回收再处理)不同。', 3, 15, 'mcq');

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.junior_grammar_points
   WHERE publisher='junior_fltrp' AND volume='wy9A';
  IF n <> 6 THEN RAISE EXCEPTION '语法点 % 个,期望 6', n; END IF;

  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A';
  IF n <> 90 THEN RAISE EXCEPTION '题目 % 道,期望 90', n; END IF;

  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U1';
  IF n <> 15 THEN RAISE EXCEPTION 'U1 % 道,期望 15', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U2';
  IF n <> 15 THEN RAISE EXCEPTION 'U2 % 道,期望 15', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U3';
  IF n <> 15 THEN RAISE EXCEPTION 'U3 % 道,期望 15', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U4';
  IF n <> 15 THEN RAISE EXCEPTION 'U4 % 道,期望 15', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U5';
  IF n <> 15 THEN RAISE EXCEPTION 'U5 % 道,期望 15', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND p.unit='U6';
  IF n <> 15 THEN RAISE EXCEPTION 'U6 % 道,期望 15', n; END IF;

  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND q.difficulty=1;
  IF n <> 42 THEN RAISE EXCEPTION 'd1 % 道,期望 42', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND q.difficulty=2;
  IF n <> 30 THEN RAISE EXCEPTION 'd2 % 道,期望 30', n; END IF;
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
    JOIN public.junior_grammar_points p ON p.id = q.point_id
   WHERE p.publisher='junior_fltrp' AND p.volume='wy9A' AND q.difficulty=3;
  IF n <> 18 THEN RAISE EXCEPTION 'd3 % 道,期望 18', n; END IF;

  -- code 前缀:本册每个点的 code 必须以 wy9a- 开头(防跨册撞全局唯一约束)
  SELECT count(*) INTO n FROM public.junior_grammar_points
   WHERE publisher='junior_fltrp' AND volume='wy9A' AND code NOT LIKE 'wy9a-%';
  IF n <> 0 THEN RAISE EXCEPTION '有 % 个点的 code 不是 wy9a- 前缀', n; END IF;

  -- 孤儿:任何题的 point_id 都必须能挂上一个存在的点
  SELECT count(*) INTO n FROM public.junior_grammar_questions q
   WHERE q.point_id IS NULL
      OR NOT EXISTS (SELECT 1 FROM public.junior_grammar_points p WHERE p.id = q.point_id);
  IF n <> 0 THEN RAISE EXCEPTION '有 % 道题的 point_id 是孤儿', n; END IF;

  -- 答案分布:每个字母不得超过 90/4 取整 +1 = 23
  SELECT count(*) INTO n FROM (
    SELECT q.correct_answer FROM public.junior_grammar_questions q
      JOIN public.junior_grammar_points p ON p.id = q.point_id
     WHERE p.publisher='junior_fltrp' AND p.volume='wy9A'
     GROUP BY q.correct_answer HAVING count(*) > 23) t;
  IF n <> 0 THEN RAISE EXCEPTION '有 % 个答案字母超过上限 23', n; END IF;

  -- 不污染其它册:wy9a- 前缀不得出现在非 wy9A 的行上
  SELECT count(*) INTO n FROM public.junior_grammar_points
   WHERE volume <> 'wy9A' AND code LIKE 'wy9a-%';
  IF n <> 0 THEN RAISE EXCEPTION '有 % 个非 wy9A 的点误用了 wy9a- 前缀', n; END IF;
END $$;

COMMIT;

-- ============================================================
-- 跑完必看:期望 6 行,total 列全 15,d1/d2/d3 = 7/5/3
-- ============================================================
SELECT p.unit, p.code, count(*) AS total,
       count(*) FILTER (WHERE q.difficulty=1) AS d1,
       count(*) FILTER (WHERE q.difficulty=2) AS d2,
       count(*) FILTER (WHERE q.difficulty=3) AS d3
  FROM public.junior_grammar_questions q
  JOIN public.junior_grammar_points p ON p.id = q.point_id
 WHERE p.publisher='junior_fltrp' AND p.volume='wy9A'
 GROUP BY p.unit, p.code ORDER BY p.unit;
